CREATE TABLE customers (id BIGSERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, email VARCHAR(255), phone VARCHAR(50));
CREATE TABLE sites (id BIGSERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, address VARCHAR(500), customer_id BIGINT NOT NULL REFERENCES customers(id));
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(200) NOT NULL, role VARCHAR(30) NOT NULL, customer_id BIGINT REFERENCES customers(id));
CREATE TABLE work_orders (id BIGSERIAL PRIMARY KEY, code VARCHAR(30) UNIQUE NOT NULL, title VARCHAR(255) NOT NULL, description TEXT, priority VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, sla_due_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ, updated_at TIMESTAMPTZ, customer_id BIGINT NOT NULL REFERENCES customers(id), site_id BIGINT NOT NULL REFERENCES sites(id), assignee_id BIGINT REFERENCES users(id));
CREATE TABLE work_order_status_history (id BIGSERIAL PRIMARY KEY, work_order_id BIGINT NOT NULL REFERENCES work_orders(id), from_status VARCHAR(30), to_status VARCHAR(30) NOT NULL, changed_by_id BIGINT NOT NULL REFERENCES users(id), changed_at TIMESTAMPTZ NOT NULL, note VARCHAR(1000));
CREATE TABLE parts (id BIGSERIAL PRIMARY KEY, name VARCHAR(200) UNIQUE NOT NULL, stock INT NOT NULL CHECK(stock >= 0), unit_cost NUMERIC(12,2) NOT NULL);
CREATE TABLE part_usage (id BIGSERIAL PRIMARY KEY, work_order_id BIGINT NOT NULL REFERENCES work_orders(id), part_id BIGINT NOT NULL REFERENCES parts(id), quantity INT NOT NULL CHECK(quantity > 0));
CREATE TABLE time_log (id BIGSERIAL PRIMARY KEY, work_order_id BIGINT NOT NULL REFERENCES work_orders(id), technician_id BIGINT NOT NULL REFERENCES users(id), minutes INT NOT NULL CHECK(minutes > 0), note VARCHAR(1000), logged_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_work_orders_status ON work_orders(status); CREATE INDEX idx_work_orders_assignee ON work_orders(assignee_id); CREATE INDEX idx_work_orders_sla ON work_orders(sla_due_at);
